import { defaultAccountsDeps, handleAccountCreate, handleAccountsList } from "../../../lib/accounts-api.ts";

// GET: the user's mail accounts (never a secret). POST: creates one (id generated by the server).
export function GET(request: Request): Response {
  return handleAccountsList(request, defaultAccountsDeps());
}

export function POST(request: Request): Promise<Response> {
  return handleAccountCreate(request, defaultAccountsDeps());
}
